def install_if_missing(import_name: str, package_name: str = None) -> None:
    package_name = package_name or import_name
    try:
        __import__(import_name)
    except ImportError:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "-q", package_name]
        )


